// --- inputs -----------------------------------------------------------------
let sfCase = actions.sfdc_int__case_email_ai.records[0];
let account = actions.get_account_details__int.records[0];

// --- account eligibility (Networks) -----------------------------------------------
// Scaffold: starts as a copy of the FAST / Homecharge rules. Corpay (Alex Godfrey, 12 Oct) will
// add corporate exclusion rules plus a bypass for named accounts; they change only this branch.
const networksBypassAccounts = [];   // Salesforce Account Ids that skip the corporate exclusion
const eligibleAdministrators = [
  "SME Unmanaged", "AS New CMT", "TFC CMT", "TFC NEW CMT", "Fuelcards4u",
  "TFC 1", "TFC 2", "TFC 3", "TFC 4", "TFC 5", "TFC 6",
  "TL AS", "TL TFC", "AS HC1", "AS HC2", "AS HC3", "AS HC4", "AS HC5"
];
let frameworkEligible = account.Framework__c == null;
let segmentEligible = account.Account_Segment__c == null
  || account.Account_Segment__c === "SME"
  || account.Account_Segment__c === "SMB"
  || account.Account_Segment__c === "Keyfuels";
let administratorEligible = eligibleAdministrators.includes(account.AS_Account_Administrator__c);

// --- pre-AI bypass gate: complaint / corporate / CCS / web or Zingtree origin ---------
// OPEN ITEM #1: confirm which Case fields carry these flags in Corpay UK Salesforce.
const bypassOrigins = ["Web", "Zingtree"];
const bypassKeywords = ["complaint", "corporate", "ccs"];
let caseText = [sfCase.Origin, sfCase.Business_process__c, sfCase.Initial_Case_Queue_Name__c, sfCase.Topic__c, sfCase.Sub_Topic__c]
  .join(" ").toLowerCase();
let bypassKeyword = bypassKeywords.find(keyword => caseText.includes(keyword));
let ai_bypass_reason = bypassOrigins.includes(sfCase.Origin)
  ? `Case origin is ${sfCase.Origin} - AI handling is bypassed in Phase 1`
  : (bypassKeyword ? `Case is flagged "${bypassKeyword}" - AI handling is bypassed in Phase 1` : "");

let ai_account_eligibility = frameworkEligible && segmentEligible && administratorEligible && ai_bypass_reason === "";

// --- what screen 9 tells the agent: every rule the account failed, in words -------
// A blank Salesforce value prints as the word Blank so the agent can see the gap.
let accountAdministrator = account.AS_Account_Administrator__c || "";
let ai_account_admin_display = accountAdministrator !== "" ? accountAdministrator : "Blank";
let ineligibleReasons = [];
if (!frameworkEligible) {
  ineligibleReasons.push("Framework is " + account.Framework__c + " - only accounts with no framework are in scope");
}
if (!segmentEligible) {
  ineligibleReasons.push("Account Segment is " + account.Account_Segment__c + " - only SME, SMB, Keyfuels or blank are in scope");
}
if (!administratorEligible) {
  if (accountAdministrator === "") {
    ineligibleReasons.push("AS Account Administrator is blank - Please work this case as you normally would.");
  } else {
    ineligibleReasons.push("AS Account Administrator " + accountAdministrator + " is not on the approved list");
  }
}
let ai_ineligible_reason = ineligibleReasons.join(". ");

// --- case status: the AI does not run on a resolved or closed case ---------------
// Checked only once the account passes, so an ineligible account still shows why.
// Salesforce Status value -> the word screen 56 prints. Corpay gave both spellings
// ("Resolve status" / "Close status" in writing, "Resolved" / "Closed" on the call).
const closedStatusWords = {
  "Resolve status": "resolved",
  "Resolved": "resolved",
  "Close status": "closed",
  "Closed": "closed"
};
let closedStatusWord = closedStatusWords[sfCase.Status] || "";
let ai_case_closed = ai_account_eligibility && closedStatusWord !== "";
let ai_case_status_notice = closedStatusWord !== "" ? "This case is " + closedStatusWord : "";

// --- outputs ----------------------------------------------------------------
ZT.setFormData("ai_account_eligibility", ai_account_eligibility);
ZT.setFormData("ai_bypass_reason", ai_bypass_reason);
ZT.setFormData("ai_account_admin_display", ai_account_admin_display);
ZT.setFormData("ai_ineligible_reason", ai_ineligible_reason);
ZT.setFormData("ai_case_closed", ai_case_closed);
ZT.setFormData("ai_case_status_notice", ai_case_status_notice);
